/// <summary>
/// AVA/WEN 2024/05/22    AVA_011496_SetColourInReqTransReqPO
/// </summary>
internal final class AVASetColourInReqTransReqPO
{
}

Method.Source:
/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{

    ReqPO       reqPO;
    ReqTrans    reqTrans;
    InventDim   updInventDim;
    Dialog                  dialog;
    DialogField             dlgfQty, dlgfColor;
    Qty                     qty;
    ItemId                  itemId;
    EcoResColorName     colorId;
    const itemId itemId200C = '1-RESDL 200 C';
    const str prodStr = 'RESDL 200 C :  :  : %1 :';
    const itemId ItemCU = '1-RESDV 200 C U';

    dialog = new Dialog("@NDX:Quantity");

    dlgfQty = dialog.addField(extendedTypeStr(qty));
    dlgfColor = dialog.addField(extendedTypeStr(AVAEcoResColorName));
    dialog.run();

    if (dialog.closedOk())
    {
        qty = dlgfQty.value();
        colorId = dlgfColor.value();
    }

    itemId = itemId200C;

    while select forupdate reqTrans where reqTrans.ItemId == itemid 
                                        && reqTrans.bomType == BOMType::Item
                                        && reqTrans.Qty == qty
    {
        updInventDim = reqTrans.inventDim();
        //if (updInventDim.InventColorId == "RAL 0000")
        //{
        updInventDim.InventColorId = colorId;
        updInventDim = InventDim::findOrCreate(updInventDim);
        ttsbegin;
        reqTrans.CovInventDimId = updInventDim.inventDimId;
        reqTrans.doUpdate();
        ttscommit;
        //}

    }
    AVASetColourHelper::createProductVariant(itemId, updInventDim);

    while select forupdate reqTrans where reqTrans.ItemId == itemId 
        //&& reqTrans.bomType == BOMType::PeggedSupply
        && reqTrans.Qty == -qty
    {
        updInventDim = reqTrans.inventDim();
        //if (updInventDim.InventColorId == "RAL 0000")
        //{
        updInventDim.InventColorId = colorId;
        updInventDim = InventDim::findOrCreate(updInventDim);
        ttsbegin;
        reqTrans.CovInventDimId = updInventDim.inventDimId;
        reqTrans.doUpdate();
        ttscommit;
        //}
    }

    while select forupdate reqPO where reqPO.ItemId == itemid && reqPO.Qty == qty
    {
        updInventDim = reqPO.inventDim();
        //if (updInventDim.InventColorId == "RAL 0000")
        //{
        updInventDim.InventColorId = colorId;
        updInventDim = InventDim::findOrCreate(updInventDim);
        ttsbegin;
        reqPO.CovInventDimId = updInventDim.inventDimId;
        reqPO.Product = EcoResProduct::findByDisplayProductNumber(strFmt(prodStr, colorId)).RecId;
        reqPO.doUpdate();
        ttscommit;
        //}
    }

    itemId = ItemCU;
    while select forupdate reqTrans where reqTrans.ItemId == itemId 
                                        && reqTrans.bomType == BOMType::Item
                                        && reqTrans.Qty == qty
    {
        updInventDim = reqTrans.inventDim();
        //if (updInventDim.InventColorId == "RAL 0000")
        //{
        updInventDim.InventColorId = colorId;
        updInventDim = InventDim::findOrCreate(updInventDim);
        ttsbegin;
        reqTrans.CovInventDimId = updInventDim.inventDimId;
        reqTrans.doUpdate();
        ttscommit;
        //}
    }
    AVASetColourHelper::createProductVariant(itemId, updInventDim);


    while select forupdate reqTrans where reqTrans.ItemId == itemid 
        //&& reqTrans.bomType == BOMType::PeggedSupply
        && reqTrans.Qty == -qty
    {
        updInventDim = reqTrans.inventDim();
        //if (updInventDim.InventColorId == "RAL 0000")
        //{
        updInventDim.InventColorId = colorId;
        updInventDim = InventDim::findOrCreate(updInventDim);
        ttsbegin;
        reqTrans.CovInventDimId = updInventDim.inventDimId;
        reqTrans.doUpdate();
        ttscommit;
        //}
    }

    while select forupdate reqPO where reqPO.ItemId == itemid && reqPO.qty == Qty
    {
        updInventDim = reqPO.inventDim();
        //if (updInventDim.InventColorId == "RAL 0000")
        //{
        updInventDim.InventColorId = colorId;
        updInventDim = InventDim::findOrCreate(updInventDim);
        ttsbegin;
        reqPO.CovInventDimId = updInventDim.inventDimId;
        reqPO.Product = EcoResProduct::findByDisplayProductNumber(strFmt(prodStr, colorId)).RecId;
        reqPO.doUpdate();
        ttscommit;
        //}
    }
}
